#!/usr/bin/env python3
"""
Validation script for pipeline outputs.
Validates selected indicators, cleaned GTFS stops, cleaned POIs,
accessibility scores, and city clusters.
"""

import csv
import json
import os
import sys


def check_file_exists(filepath):
    """Check if a file exists."""
    return os.path.isfile(filepath)


def check_csv_has_columns(filepath, required_columns):
    """Check if CSV file has required columns."""
    if not check_file_exists(filepath):
        return False, f"File {filepath} does not exist"
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            headers = reader.fieldnames
            if headers is None:
                return False, "CSV file has no headers"
            missing = [col for col in required_columns if col not in headers]
            if missing:
                return False, f"Missing columns: {missing}"
            return True, f"All required columns present: {required_columns}"
    except Exception as e:
        return False, f"Error reading CSV: {e}"


def check_csv_has_rows(filepath, min_rows=1):
    """Check if CSV file has minimum number of rows."""
    if not check_file_exists(filepath):
        return False, f"File {filepath} does not exist"
    try:
        row_count = 0
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            next(reader, None)  # Skip header
            for _ in reader:
                row_count += 1
        if row_count < min_rows:
            return False, f"File has only {row_count} rows, expected at least {min_rows}"
        return True, f"File contains {row_count} rows"
    except Exception as e:
        return False, f"Error reading CSV: {e}"


def check_numeric_columns(filepath, numeric_columns):
    """Check if specified columns contain valid numeric values."""
    if not check_file_exists(filepath):
        return False, f"File {filepath} does not exist"
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            for row in reader:
                for col in numeric_columns:
                    if col in row and row[col]:
                        try:
                            float(row[col])
                        except ValueError:
                            return False, f"Non-numeric value in column {col}: {row[col]}"
            return True, f"All values in columns {numeric_columns} are numeric"
    except Exception as e:
        return False, f"Error reading CSV: {e}"


def check_json_valid(filepath):
    """Check if JSON file is valid."""
    if not check_file_exists(filepath):
        return False, f"File {filepath} does not exist"
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            json.load(f)
        return True, "JSON file is valid"
    except json.JSONDecodeError as e:
        return False, f"Invalid JSON: {e}"
    except Exception as e:
        return False, f"Error reading JSON: {e}"


def check_cluster_distribution(filepath):
    """Check that city clusters have valid cluster_id values."""
    if not check_file_exists(filepath):
        return False, f"File {filepath} does not exist"
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            cluster_ids = set()
            for row in reader:
                if 'cluster_id' in row:
                    cluster_ids.add(row['cluster_id'])
            if len(cluster_ids) == 0:
                return False, "No cluster_id values found"
            return True, f"Found {len(cluster_ids)} unique cluster(s): {sorted(cluster_ids)}"
    except Exception as e:
        return False, f"Error reading CSV: {e}"


def main():
    """Run all validation checks and write summary."""
    outputs_dir = "outputs"
    results = []

    # Check 1: Selected indicators file
    indicators_file = os.path.join(outputs_dir, "t01_selected_indicators.csv")
    required_cols = ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"]
    passed, message = check_csv_has_columns(indicators_file, required_cols)
    results.append({
        "check_name": "selected_indicators_columns",
        "passed": passed,
        "message": message
    })

    # Check 2: Selected indicators has data rows
    passed, message = check_csv_has_rows(indicators_file, min_rows=5)
    results.append({
        "check_name": "selected_indicators_has_data",
        "passed": passed,
        "message": message
    })

    # Check 3: Clean GTFS stops file
    stops_file = os.path.join(outputs_dir, "t05_clean_stops.csv")
    required_cols = ["stop_id", "stop_name", "stop_lat", "stop_lon"]
    passed, message = check_csv_has_columns(stops_file, required_cols)
    results.append({
        "check_name": "clean_stops_columns",
        "passed": passed,
        "message": message
    })

    # Check 4: Clean GTFS stops has valid coordinates
    passed, message = check_numeric_columns(stops_file, ["stop_lat", "stop_lon"])
    results.append({
        "check_name": "clean_stops_coordinates_valid",
        "passed": passed,
        "message": message
    })

    # Check 5: Clean POIs file
    pois_file = os.path.join(outputs_dir, "t08_pois_clean.csv")
    required_cols = ["qid", "label", "poi_type", "latitude", "longitude", "source"]
    passed, message = check_csv_has_columns(pois_file, required_cols)
    results.append({
        "check_name": "clean_pois_columns",
        "passed": passed,
        "message": message
    })

    # Check 6: Clean POIs has data
    passed, message = check_csv_has_rows(pois_file, min_rows=10)
    results.append({
        "check_name": "clean_pois_has_data",
        "passed": passed,
        "message": message
    })

    # Check 7: Accessibility scores file
    accessibility_file = os.path.join(outputs_dir, "t10_accessibility_scores.csv")
    required_cols = ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"]
    passed, message = check_csv_has_columns(accessibility_file, required_cols)
    results.append({
        "check_name": "accessibility_scores_columns",
        "passed": passed,
        "message": message
    })

    # Check 8: Accessibility scores has valid numeric values
    passed, message = check_numeric_columns(accessibility_file, ["distance_m", "accessibility_score"])
    results.append({
        "check_name": "accessibility_scores_numeric_valid",
        "passed": passed,
        "message": message
    })

    # Check 9: City clusters file
    clusters_file = os.path.join(outputs_dir, "t13_city_clusters.csv")
    required_cols = ["city_id", "city_name", "year", "cluster_id"]
    passed, message = check_csv_has_columns(clusters_file, required_cols)
    results.append({
        "check_name": "city_clusters_columns",
        "passed": passed,
        "message": message
    })

    # Check 10: City clusters has valid cluster distribution
    passed, message = check_cluster_distribution(clusters_file)
    results.append({
        "check_name": "city_clusters_distribution",
        "passed": passed,
        "message": message
    })

    # Check 11: GTFS summary JSON file
    gtfs_summary_file = os.path.join(outputs_dir, "t04_gtfs_summary.json")
    passed, message = check_json_valid(gtfs_summary_file)
    results.append({
        "check_name": "gtfs_summary_json_valid",
        "passed": passed,
        "message": message
    })

    # Write validation summary
    output_file = os.path.join(outputs_dir, "t14_validation_summary.json")
    with open(output_file, 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=2)

    print(f"Validation complete. Results written to {output_file}")
    print(f"Total checks: {len(results)}")
    passed_count = sum(1 for r in results if r["passed"])
    print(f"Passed: {passed_count}/{len(results)}")

    return 0 if passed_count == len(results) else 1


if __name__ == "__main__":
    sys.exit(main())

